   "card": {
    "fk": "HIV is an enveloped +ssRNA lentivirus (retrovirus) that binds CD4 plus CCR5 or CXCR4. It reverse-transcribes its genome and integrates it as a provirus, which host RNA polymerase II transcribes. Progressive CD4 T-cell loss through direct killing, CTL killing and chronic immune activation leads, untreated, to AIDS (CD4 <200/µL or opportunistic disease). Latent provirus in resting memory CD4 T cells makes it incurable.",
    "v": [
     "HIV-1 from chimpanzee SIV (group M ~95%), HIV-2 from mangabeys (less virulent, West Africa)",
     "gp120 binds CD4 plus CCR5 (macrophage-tropic, transmitted) or CXCR4 (T-cell-tropic, later); gp41 fusion; RT, integrase, protease",
     "Phases: acute (high viraemia, GALT CD4 depletion), asymptomatic, symptomatic, AIDS; death from opportunistic infections",
     "Antibodies fall late because CD4 T-helper cells needed for B-cell help are lost",
     "CNS: Trojan horse via infected monocytes; infects microglia, causing HIV-associated dementia",
     "Transmission: sexual 70-80%, needle sharing second, vertical (delivery, breastfeeding); no vaccine because of antigenic variability"
    ],
    "m": "AIDS is defined by CD4 below 200/µL or AIDS-defining opportunistic disease, and untreated patients die of opportunistic infections.",
    "k": "Enveloped diploid +ssRNA lentivirus; reverse transcriptase, integrase, protease; Env gp120/gp41; integrated latent provirus in resting CD4 memory T cells.",
    "d": "Combined antibody/p24 antigen test, HIV RNA viral load, CD4 count; PCR in infants.",
    "b": "Lifelong combination ART; no vaccine; prevention with condoms, PrEP/PEP, needle exchange and PMTCT.",
    "src": "t3b-116"
   },
