   "card": {
    "fk": "Acute inflammation starts with mediator release (histamine, prostaglandins, leukotrienes, cytokines), vasodilation and leakage. Leukocytes then extravasate actively: selectin-mediated rolling, chemokine-induced integrin activation, firm adhesion to ICAM-1/VCAM-1, diapedesis, MMP breakdown of matrix and chemotaxis along gradients of IL-8, C5a, fMLP and LTB4.",
    "v": [
     "Rolling: E-/P-selectin bind sialyl-Lewis X (PSGL-1); fast on/off kinetics",
     "Chemokines on endothelium → GPCR → integrin high-affinity switch (inside-out)",
     "Firm adhesion: LFA-1/Mac-1–ICAM-1, VLA-4–VCAM-1",
     "Diapedesis via PECAM-1; MMPs (collagenases, gelatinases) degrade ECM",
     "Chemoattractants: IL-8/CXCL8, C5a, fMLP, LTB4",
     "LAD I (CD18), II (selectin ligand), III (integrin activation)",
     "Lymph node entry via HEV: L-selectin, CCL19/21–CCR7; B cells CXCL13–CXCR5"
    ],
    "m": "Extravasation is an active multistep process – rolling (selectins), activation (chemokines), adhesion (integrins), diapedesis, chemotaxis.",
    "k": "",
    "d": "",
    "b": "Glucocorticoids, NSAIDs, anti-TNF and anti-integrin antibodies (natalizumab, vedolizumab) target inflammation and migration.",
    "src": "t3b-140"
   },
