   "card": {
    "fk": "Influenza is an enveloped, 8-segment negative-sense RNA virus with HA (binds sialic acid) and NA (releases virions). Error-prone polymerase causes point mutations in HA/NA (drift), giving annual epidemics and the yearly vaccine update. Reassortment of segments between human and animal influenza A viruses (shift) creates new subtypes and pandemics.",
    "v": [
     "Influenza A has 18 H and 11 N subtypes; A and B cause epidemics; only A causes pandemics, and it has caused the most pandemics in history",
     "Drift: point mutations (A and B); shift: reassortment, e.g. in pigs carrying both alpha-2,3 and alpha-2,6 sialic acid",
     "Human viruses bind alpha-2,6 (upper airway); avian H5N1 binds alpha-2,3, found only in the lower airways, so infection needs a high dose",
     "Neuraminidase inhibitors (oseltamivir, zanamivir) block release, start within 48 h; baloxavir blocks cap-snatching; amantadine (M2) is obsolete",
     "Vaccine: inactivated split/subunit HA/NA grown in eggs (or live nasal for children), updated every year",
     "Diagnosis by RT-PCR of a nasopharyngeal swab; adults are minimally infectious after about 5 days"
    ],
    "m": "Drift (point mutations) gives seasonal epidemics; shift (segment reassortment, influenza A only) gives pandemics.",
    "k": "Segmented -ssRNA orthomyxovirus; HA binds sialic acid and is cleaved by host proteases; NA releases progeny; NS1 antagonises interferon.",
    "d": "RT-PCR on a nasopharyngeal/throat swab; rapid antigen tests; culture for surveillance.",
    "b": "Neuraminidase inhibitors or baloxavir for risk groups; annual inactivated vaccine for the elderly, pregnant women, risk groups and staff.",
    "src": "t3b-108"
   },
   "has_card": true,
