   "card": {
    "fk": "Exotoxins are secreted bacterial proteins grouped by mechanism: superantigens bind the cell surface without entering, cytolytic toxins destroy membrane integrity, and A-B toxins act on intracellular proteins. In an A-B toxin the B part binds the receptor without toxic effect and the A part enters and is enzymatically active, often an ADP-ribosyltransferase.",
    "v": [
     "Cholera toxin and ETEC LT: B pentamer binds GM1, A1 ADP-ribosylates Gs-alpha, adenylate cyclase is locked on, cAMP rises, PKA opens CFTR giving chloride secretion and watery diarrhoea without mucosal damage.",
     "Pertussis toxin ADP-ribosylates Gi-alpha so adenylate cyclase is no longer inhibited; cAMP also rises.",
     "Diphtheria toxin (phage-encoded, iron-regulated) binds HB-EGF, and its A fragment ADP-ribosylates elongation factor 2, stopping protein synthesis - one molecule can kill a cell.",
     "Shiga toxin cleaves an adenine from 28S rRNA of the 60S subunit and also stops protein synthesis, causing HUS.",
     "Botulinum toxin cleaves SNAREs and blocks acetylcholine release (flaccid paralysis); tetanospasmin cleaves synaptobrevin and blocks GABA/glycine release (spastic paralysis).",
     "Toxoid vaccines (diphtheria, tetanus, acellular pertussis) and antitoxin are the specific prevention and treatment."
    ],
    "m": "Cholera toxin does not inhibit protein synthesis; it raises cAMP. Protein synthesis inhibition is the signature of diphtheria and Shiga toxins.",
    "k": "V. cholerae, ETEC, B. pertussis, C. diphtheriae, Shigella/EHEC, C. botulinum, C. tetani, C. difficile, S. aureus, S. pyogenes, P. aeruginosa.",
    "d": "Toxin gene PCR (stx1/stx2, tox, ctxA), toxin EIA in stool for C. difficile, culture on cystine-tellurite medium for C. diphtheriae, toxin detection in serum or food for botulism.",
    "b": "Antitoxin or immunoglobulin neutralises circulating toxin, clindamycin stops further toxin synthesis, oral rehydration treats cholera, and toxoid vaccination prevents the toxin-mediated diseases.",
    "src": "t3b-065"
   },
