   "card": {
    "fk": "Resistance spreads by selection: antibiotics kill sensitive bacteria, and resistant mutants (10^-4–10^-10 per division; stepwise at increasing concentrations) or bacteria with acquired genes survive. Genes move by transformation, transduction and, most importantly, conjugation of R-plasmids carrying transposons and integrons. Key threats are MRSA (mecA/PBP2a), ESBL and carbapenemase producers (CTX-M, NDM-1, KPC), VRE (vanA, D-Ala-D-Lac) and resistant gonococci.",
    "v": [
     "Antibiotics select pre-existing mutants; stepwise mutations give rising MIC at low concentrations",
     "HGT: transformation (competent), transduction (phage), conjugation (pilus, oriT; most important)",
     "R-plasmid = RTF (tra, oriT) + R determinant (resistance genes, transposons e.g. Tn21)",
     "Transposon = transposase + cargo genes; IS element = transposase only; integron = IntI + attI + promoter",
     "VRSA: vanA (Tn1546) from VRE plasmid to MRSA by conjugation",
     "MRSA, VRE and ESBL-CARBA notifiable with mandatory contact tracing (smittspårningspliktiga); ESBL notifiable",
     "Stewardship (Strama), hand hygiene, screening after care abroad"
    ],
    "m": "Conjugation of multiresistance plasmids is the most important route for spreading resistance genes, even between species.",
    "k": "Mutation + selection, or acquisition of mobile genetic elements (plasmids, transposons, integrons).",
    "d": "Screening cultures and PCR for mecA, vanA, CTX-M and carbapenemases; WGS for outbreak tracing.",
    "b": "Narrow spectrum, correct dose and duration, infection control, surveillance and notification.",
    "src": "t3b-173"
   },
