   "card": {
    "fk": "Antivirals block virus-specific steps of the life cycle: entry/fusion (maraviroc, enfuvirtide, RSV antibodies), uncoating (amantadine), replication (acyclovir, NRTI/NNRTI, baloxavir, remdesivir), integration (integrase inhibitors), polyprotein processing (protease inhibitors) and release (neuraminidase inhibitors). Acyclovir is a prodrug activated by viral thymidine kinase that causes chain termination, so it has few side effects. Drugs mainly exist against HIV, HCV, HBV, herpesviruses, influenza, RSV and SARS-CoV-2.",
    "v": [
     "Acyclovir: prodrug, viral TK phosphorylates first, chain termination; only active in infected cells",
     "Protease inhibitors: HCV NS3/4A early (polyprotein); HIV late (maturation → non-infectious virions)",
     "Integrase inhibitors (dolutegravir): block strand transfer, so no integration of HIV DNA",
     "Influenza: NA inhibitors Tamiflu/Relenza (block release), baloxavir/Xofluza (no cap-snatching, no viral mRNA), M2 blockers",
     "HIV entry: ibalizumab, fostemsavir, maraviroc (CCR5), enfuvirtide (gp41)",
     "Prodrug = inactive compound converted to the active form in the body",
     "Few antivirals: intracellular virus, host similarity, acute infections, lack of rapid diagnostics"
    ],
    "m": "Acyclovir has few side effects because viral thymidine kinase is needed to activate it, so it acts only in infected cells.",
    "k": "Targets viral enzymes and proteins: polymerase/RT, integrase, protease, neuraminidase, PA endonuclease, entry proteins.",
    "d": "Rapid diagnosis is needed for early treatment; resistance is detected by sequencing.",
    "b": "Combination therapy for HIV/HCV; early start in influenza/HSV; PrEP with tenofovir/emtricitabine.",
    "src": "t3b-174"
   },
