   "card": {
    "fk": "Sepsis is life-threatening organ dysfunction caused by a dysregulated host response to infection (Sepsis-3), operationally an infection with an acute rise in SOFA of at least 2 points. Septic shock adds vasopressor-dependent hypotension and lactate above 2 mmol/l despite fluid resuscitation. Bacteria are the most common cause, and the innate immune system dominates the pathogenesis.",
    "v": [
     "SOFA covers six systems: respiratory (PaO2/FiO2), coagulation (platelets), liver (bilirubin), cardiovascular (MAP/vasopressors), CNS (GCS) and renal (creatinine/urine output); qSOFA uses respiratory rate, mentation and systolic blood pressure.",
     "Organ dysfunction arises from capillary leakage with endothelial dysfunction, epithelial barrier dysfunction and impaired cellular metabolism.",
     "The response is imbalanced with both over- and under-activation: T lymphocytes undergo increased apoptosis giving immunosuppression and secondary infection, while neutrophil apoptosis is decreased.",
     "DIC causes both thrombosis and bleeding, the bleeding resulting from consumption of coagulation factors and platelets.",
     "E. coli is the most common organism in Swedish intensive care sepsis; the commonest sites of origin are lung, urinary tract, skin/soft tissue and abdomen.",
     "Risk factors: higher age, male sex, chronic illness (diabetes, COPD, malignancy), immunosuppressive drugs, alcohol and intravenous drug abuse, and indwelling foreign material."
    ],
    "m": "Cultures must not delay antibiotics in septic shock, and neither a normal CRP nor a normal or low white cell count excludes sepsis.",
    "k": "Gram-negatives dominate (E. coli, Klebsiella), then Gram-positives (S. aureus, pneumococci, beta-haemolytic streptococci) and fungi; LPS/lipid A via TLR4 is the classical trigger.",
    "d": "Blood culture x2, urine culture and dipstick, cultures from suspected foci, viral diagnostics, pneumococcal and Legionella urinary antigen, rapid GAS test in necrotising infection, plus blood gas with lactate, blood count, CRP, creatinine, coagulation and liver tests.",
    "b": "Early broad-spectrum intravenous antibiotics, fluids, oxygen, vasopressors, source control by drainage or debridement, antipyretics and steroids as indicated, followed by de-escalation, rehabilitation planning and follow-up.",
    "src": "t3b-074"
   },
