   "card": {
    "fk": "HIV is diagnosed with combined antibody plus p24 antigen immunoassays (confirmed by a second test and HIV RNA). The window period is the time from infection until markers, classically antibodies, become detectable. Lifelong combination ART (NRTI, NNRTI, integrase and protease inhibitors, entry inhibitors) suppresses the virus to undetectable levels, but stopping it causes rebound from the latent reservoir.",
    "v": [
     "4th-generation combo test (antibody + p24) shortens the window period; p24/PCR for infants; viral load and CD4 for monitoring",
     "NRTI: chain terminators activated by cellular kinases (more side effects); NNRTI: allosteric RT inhibitors",
     "Integrase inhibitors block strand transfer; protease inhibitors give immature non-infectious virions; maraviroc blocks CCR5; enfuvirtide blocks gp41 fusion",
     "Combination because the error-prone RT gives resistant mutants: higher potency, less resistance",
     "Stopping ART: rebound within weeks from latent resting CD4 T cells; no cure",
     "Prevention: PrEP (tenofovir/emtricitabine), PEP within 72 h for 28 days, U=U, PMTCT (<1% transmission), condoms, needle exchange"
    ],
    "m": "ART never eradicates the integrated provirus, so treatment is lifelong and stopping it brings the virus back within weeks.",
    "k": "Drugs target entry (CD4, CCR5, gp41), reverse transcription (NRTI, NNRTI), integration (INSTI) and maturation (protease).",
    "d": "Combined antibody/p24 immunoassay with confirmation; HIV RNA PCR for acute infection, infants and viral load; CD4 count.",
    "b": "Lifelong combination ART (e.g. 2 NRTI + integrase inhibitor); PrEP, PEP, condoms, needle exchange, PMTCT; U=U.",
    "src": "t3b-117"
   },
