     "Subunit: HBsAg (yeast), HPV L1 VLP, influenza HA/NA, acellular pertussis",
     "Toxoid: diphtheria, tetanus; conjugate: Hib, PCV, MenACWY (T-dependent, works in infants)",
     "Vector: AstraZeneca, Janssen, Sputnik (adenovirus); Ebola rVSV",
     "mRNA (Pfizer, Moderna): LNP mRNA translated in our cells, MHC I and II, fast to redesign, cold chain"
