   "card": {
    "fk": "β-lactams (penicillins, cephalosporins, carbapenems) mimic D-Ala-D-Ala and irreversibly acylate the active serine of the transpeptidase (PBP), so peptidoglycan is not cross-linked; autolysins and osmotic pressure (about 2 atm) then lyse the bacterium. Vancomycin blocks the same step by binding D-Ala-D-Ala on the precursor; it works only against Gram-positives. Both work only on growing bacteria and not on Mycoplasma.",
    "v": [
     "Target: PBP/transpeptidase, i.e. cross-linking of the cell wall; bacteriolytic",
     "Only growing bacteria, so do not combine with bacteriostatic drugs (antagonism)",
     "Penicillin G iv (acid labile), V oral; methicillin/oxacillin β-lactamase stable; ampicillin broad",
     "Cephalosporins low toxicity, broad; carbapenems broadest; clavulanic acid inhibits β-lactamase",
     "Resistance: β-lactamases (ESBL, NDM-1), PBP2a (MRSA), porin loss; VRE: D-Ala-D-Lac",
     "Mycoplasma lacks a cell wall, so use macrolides/tetracyclines/quinolones",
     "Adverse effects: penicillin allergy; vancomycin oto- and nephrotoxic"
    ],
    "m": "β-lactams and vancomycin both stop cell wall cross-linking but by different mechanisms (enzyme vs substrate), and neither works on Mycoplasma.",
    "k": "Irreversible PBP inhibition (β-lactam) or D-Ala-D-Ala binding (vancomycin) stops transpeptidation.",
    "d": "",
    "b": "Narrow-spectrum penicillin V for streptococci; flucloxacillin for S. aureus; vancomycin for MRSA; carbapenems for ESBL.",
    "src": "t3b-169"
   },
