   "card": {
    "fk": "The Communicable Diseases Act (smittskyddslagen 2004:168) protects the population from communicable diseases. It classifies diseases as notifiable, subject to contact tracing, threat to public health (allmänfarliga) and threat to society, and sets obligations for patients and treating physicians.",
    "v": [
     "Patient (allmänfarlig): seek care, be tested, follow rules of conduct, contribute to contact tracing – taking treatment is not an obligation",
     "Physician: test, inform, give rules of conduct, initiate contact tracing, notify, report non-compliance to the smittskyddsläkare",
     "Suspicion criteria: typical symptoms, considerable exposure risk, notified via contact tracing",
     "Allmänfarliga include STI, HIV, hepatitis A–E, TB, salmonella, shigella, campylobacter, EHEC; free of charge (MRSA is smittspårningspliktig, not allmänfarlig)",
     "COVID-19 is currently only notifiable",
     "Rules of conduct are given on clinical suspicion after sampling"
    ],
    "m": "Taking treatment is not a legal obligation under the Act – but seeking care, testing, rules of conduct and contact tracing are.",
    "k": "",
    "d": "",
    "b": "Notify, trace contacts and give rules of conduct; compulsory isolation is a last resort via the smittskyddsläkare and court.",
    "src": "t3b-186"
   },
