   "card": {
    "fk": "Vibrio cholerae is a curved, motile Gram-negative rod that colonises the small intestine with the toxin-coregulated pilus and secretes cholera toxin. The toxin raises cAMP so that chloride and water pour into the lumen, giving profuse rice-water diarrhoea, dehydration and hypovolaemic shock without mucosal damage.",
    "v": [
     "Two key virulence factors: cholera toxin (fluid secretion) and toxin-coregulated pilus (colonisation)",
     "Cholera toxin is an AB5 toxin: B subunits bind GM1, A1 ADP-ribosylates Gs alpha, adenylate cyclase stays on, cAMP rises, PKA opens CFTR",
     "Massive watery rice-water diarrhoea, no fever and no blood; hypokalaemia and acidosis",
     "Spread by contaminated water and food; the bacterium is acid-sensitive",
     "Diagnosis: microscopy of curved rods, culture on TCBS agar, antigen test/PCR",
     "Treatment: fluid and electrolyte replacement (ORS) first, antibiotics to clear the organism",
     "V. parahaemolyticus causes diarrhoea after raw seafood; it is halophilic with haemolysin and adhesin"
    ],
    "m": "Cholera toxin increases cAMP and does not inhibit protein synthesis, and rehydration takes priority over antibiotics.",
    "k": "Cholera toxin (AB5) locks Gs alpha active via ADP-ribosylation, giving sustained adenylate cyclase activity and CFTR-mediated secretion.",
    "d": "Curved Gram-negative rods on microscopy, culture on TCBS selective agar, rapid antigen test or PCR, serogrouping O1/O139.",
    "b": "Oral or intravenous rehydration, adjunct doxycycline; prevention by safe water, sanitation, hygiene and oral cholera vaccines (Dukoral, Shanchol).",
    "src": "t3b-081"
   },
