    "fk": "Viral vaccines cover every platform: live (MMR, varicella, rotavirus, yellow fever, OPV), inactivated (IPV, hepatitis A, rabies, TBE), subunit (influenza HA/NA, HBsAg, HPV VLP), vector and mRNA (COVID-19). The Swedish childhood programme includes rotavirus, polio (IPV), hepatitis B, MMR and HPV. HPV vaccination (Gardasil 9) has included boys since 2020.",
