     "Rotavirus: oral live, 6 weeks-5 months, programme since 2019",
     "Hexavalent DTaP-IPV-Hib-HepB + PCV at 3, 5, 12 months; MMR at 18 months and 6-8 years",
     "HPV: L1 VLP from yeast; Gardasil 9 (6,11,16,18,31,33,45,52,58) ~90% protection; girls 2010/2012, boys 2020",
     "Hepatitis B: recombinant HBsAg; vaccinated = anti-HBs only",
     "Influenza: egg-grown, inactivated, HA/NA purified; updated yearly for drift",
     "COVID-19: mRNA (Pfizer, Moderna) vs adenovirus vectors (AstraZeneca, Janssen)"
