     "Conjugation is most problematic for resistance – multi-resistance R-plasmids, broad host range",
     "R-plasmid = RTF (transfer genes) + R-determinant (resistance genes, transposons, integrons)",
     "IS = only transposase; transposon = transposase + cargo genes; both need transposase",
     "Integron: IntI, attI, promoter; cassettes have attC",
