   "card": {
    "fk": "Prions are misfolded, β-sheet-rich forms (PrPSc) of the host prion protein PrPC that convert normal PrPC by templating and contain no nucleic acid. They cause fatal spongiform encephalopathies: sporadic, genetic and iatrogenic CJD, vCJD from BSE beef or blood, and kuru from ritual cannibalism. RT-QuIC amplifies tiny amounts of prion seed for diagnosis; there is no treatment, and decontamination needs 134 °C for at least 18 min plus NaOH/hypochlorite.",
    "v": [
     "PrPC (α-helical, protease-sensitive, conserved 3D structure) → PrPSc (β-sheet amyloid, protease-resistant)",
     "Accumulates in CNS and lymphoreticular tissue, especially spleen",
     "Routes: BSE beef (vCJD), kuru (cannibalism), neurosurgical instruments, dura/cornea grafts, cadaveric GH, blood transfusion",
     "RT-QuIC/PMCA amplify PrPSc seeds – sensitive ante-mortem diagnosis",
     "No curative treatment, no vaccine; always fatal",
     "Resistant to autoclaving at 121 °C, formaldehyde, alcohol, UV – use 134 °C ≥18 min + 1–2 M NaOH or hypochlorite, single-use instruments, incineration",
     "BSE lessons: feed ban, removal of risk material, blood donor restrictions"
    ],
    "m": "Prions are infectious proteins without nucleic acid that survive standard sterilisation, are diagnosed by RT-QuIC and have no treatment.",
    "k": "Misfolded PrPSc templates conversion of host PrPC into β-sheet amyloid; spongiform neurodegeneration without inflammation.",
    "d": "RT-QuIC (CSF, nasal brushings), MRI, EEG, CSF 14-3-3/tau; neuropathology/tonsil biopsy (vCJD).",
    "b": "No curative treatment; prevention by feed bans, risk-material removal, blood safety, single-use instruments and prion-specific decontamination.",
    "src": "t3b-059"
   },
