   "card": {
    "fk": "HSV-1 and HSV-2 are alphaherpesviruses (enveloped dsDNA) that infect mucosal epithelium lytically and then go latent in sensory ganglia: trigeminal for oral herpes, sacral for genital herpes. Reactivation (UV, stress, fever) sends the virus anterogradely back to the same skin area. HSV-1 causes herpes labialis, keratitis and encephalitis; HSV-2 causes genital herpes, meningitis and most neonatal herpes.",
    "v": [
     "Primary infection in epithelium, then retrograde axonal transport to the ganglion; latency with only LAT transcripts",
     "Reactivation by UV, stress, fever or immunosuppression leads to anterograde transport and a local vesicle; asymptomatic shedding spreads it",
     "Encephalitis: HSV-1, temporal lobe, 70% mortality untreated; give iv acyclovir immediately",
     "Neonatal herpes: ~50% transmission with primary maternal infection at delivery, ~2% with reactivation; disseminated disease",
     "Acyclovir: guanosine analogue prodrug, phosphorylated first by viral TK, chain terminator of viral DNA polymerase",
     "No vaccine; latency cannot be eliminated"
    ],
    "m": "Suspected HSV encephalitis means high-dose iv acyclovir immediately, before PCR results.",
    "k": "Enveloped dsDNA alphaherpesvirus with broad tropism (gD binds nectin-1/HVEM); latent in sensory neurons as an episome expressing only LATs.",
    "d": "Type-specific PCR on vesicle fluid or CSF; MRI shows temporal lobe changes in encephalitis.",
    "b": "Acyclovir/valacyclovir (viral TK-dependent chain terminators); foscarnet for TK-resistant strains; no vaccine.",
    "src": "t3b-104"
   },
