   "card": {
    "fk": "VZV (HHV-3) is an alphaherpesvirus. It is inhaled, multiplies in tonsils and lymph nodes, infects T cells and spreads by two viraemias (liver/spleen, then skin) to give chickenpox. It then goes latent in dorsal root and cranial nerve ganglia and can reactivate decades later as painful dermatomal shingles, mainly in the elderly and immunocompromised.",
    "v": [
     "Airborne, extremely contagious from 1-2 days before the rash until crusting; incubation about 2 weeks",
     "Chickenpox: itchy vesicular rash in crops at different stages; adult complications include pneumonia",
     "Latency in sensory neurons of dorsal root/cranial ganglia; reactivation gives unilateral dermatomal zoster",
     "Zoster complications: postherpetic neuralgia, zoster ophthalmicus, Ramsay Hunt, dissemination in the immunocompromised",
     "Only herpesvirus with a vaccine: live attenuated varicella vaccine; zoster vaccines for older adults",
     "Acyclovir/valacyclovir; VZIG for exposed immunocompromised or pregnant non-immune people"
    ],
    "m": "Shingles is reactivation of latent VZV from sensory ganglia, not a new infection, and the virus can never be cured.",
    "k": "Enveloped dsDNA alphaherpesvirus with thymidine kinase; infects T cells, epithelium and keratinocytes; latent in sensory neurons.",
    "d": "Clinical diagnosis; PCR of vesicle fluid to confirm; VZV IgG to check immunity.",
    "b": "Acyclovir/valacyclovir; live attenuated varicella vaccine and zoster vaccines; VZIG as passive prophylaxis.",
    "src": "t3b-105"
   },
