   "card": {
    "fk": "Neisseria gonorrhoeae is a fastidious Gram-negative kidney-shaped diplococcus and obligate human pathogen causing gonorrhoea. It adheres via type IV pili and Opa proteins, triggers purulent neutrophil inflammation and evades antibodies by antigenic and phase variation. Antibiotic resistance, including reduced ceftriaxone susceptibility, is a growing problem.",
    "v": [
     "Gram-negative diplococci, often inside neutrophils; grows on chocolate agar in CO2",
     "Incubation 2–8 days; men purulent urethritis; women often asymptomatic cervicitis → PID, infertility",
     "Virulence: type IV pili, Opa, PorB, LOS, IgA1 protease, efflux pumps, iron acquisition",
     "Antigenic variation (pilS → pilE recombination) and phase variation (Opa, slipped-strand mispairing) → no immunity, no vaccine",
     "NAAT for detection (confirm with second test due to low PPV), culture for susceptibility",
     "Ceftriaxone i.m. single dose (plus azithromycin for pharyngeal); resistance to many classes"
    ],
    "m": "Gonorrhoea is the bacterial STI where antibiotic resistance is increasing – always culture for susceptibility.",
    "k": "Extracellular Gram-negative diplococcus with pili, Opa, PorB and LOS; massive antigenic and phase variation; naturally competent.",
    "d": "NAAT on urine/swab with confirmatory second test; culture for susceptibility testing; Gram stain in symptomatic men.",
    "b": "Ceftriaxone single i.m. dose (plus azithromycin if pharyngeal), partner treatment, test of cure and contact tracing.",
    "src": "t3b-095"
   },
