   "card": {
    "fk": "Acute infections are rapid and self-limiting, whereas persistent infections last long term, often for the life of the host, with virus produced at low levels either continuously or intermittently. The genome can remain even without viral proteins being made, which is the basis of latency, and the pattern is characteristic for each virus.",
    "v": [
     "Requirements: avoid killing the host cell, maintain the genome as episome or integrated provirus, evade immunity, and be able to reactivate.",
     "Three factors help persistence: reduced immune surveillance (CNS, eye, testicle, lymphoid cells), infection of immune cells, and viral immune modulation such as MHC I interference.",
     "HSV and VZV are latent in sensory ganglion neurons as circular episomes expressing only LAT transcripts and miRNAs, so no viral proteins are presented; neurons also have low MHC class I.",
     "EBV and HHV-8 are latent in B cells, CMV in monocytes and lymphocytes, HHV-6 and HHV-7 in T cells; HIV integrates as a provirus.",
     "Polyomaviruses persist in kidney, intestine and CNS by an unknown mechanism and cause BK nephropathy, JC-driven PML and Merkel cell cancer in the immunosuppressed.",
     "Up to 90% of infants but only about 5% of adults become chronic HBV carriers, because a poor T-cell response gives few symptoms but no elimination."
    ],
    "m": "Latent VZV and HSV reside in nerve cells of sensory ganglia, and reactivation follows loss of T-cell control.",
    "k": "Herpesviruses, polyomaviruses (BK, JC, Merkel cell), HPV, HBV, HCV, HIV, HTLV, measles (SSPE), rubella (progressive panencephalitis), adenovirus.",
    "d": "PCR of the relevant compartment (CSF, plasma, urine) quantifies reactivation; serology shows past infection; pre-transplant serostatus guides monitoring.",
    "b": "Suppression rather than cure: aciclovir for HSV/VZV, valganciclovir for CMV, ART for HIV, tenofovir for HBV; prevent with HBV, HPV, varicella and zoster vaccination and graft screening.",
    "src": "t3b-072"
   },
