   "card": {
    "fk": "Bacterial immune evasion covers resistance to antimicrobial peptides, complement, phagocytosis and NETs, and escape from antibodies and T cells. For extracellular pathogens the central strategy is phenotypic variation of surface structures: phase variation switches a structure on or off, while antigenic variation expresses different antigenic forms of the same molecule.",
    "v": [
     "Phase variation: reversible ON/OFF switching by slipped-strand mispairing, DNA inversion or methylation; the antigen itself is unchanged (Opa proteins, fimbriae).",
     "Antigenic variation: gene conversion from silent cassettes into an expression locus changes the amino acid sequence (pilS to pilE in N. gonorrhoeae, Borrelia VlsE, trypanosome VSG, TprK in T. pallidum).",
     "Capsule covers surface structures and blocks complement activation and hence phagocytosis; slime layers instead serve adhesion and biofilm.",
     "Molecular mimicry: hyaluronic acid capsule in S. pyogenes and sialic acid capsule in N. meningitidis are host-like and do not activate the immune defence.",
     "Other strategies: IgA1 protease, IgG Fc-cleaving proteases (IdeS, EndoS), protein A and protein H covering IgG Fc, C5a peptidase blocking chemotaxis, DNases degrading NETs, induction of IL-10, intracellular survival.",
     "N. gonorrhoeae has about a million pilus variants and phase varies over 100 genes, which is why there is no lasting immunity and no vaccine."
    ],
    "m": "An immunodominant surface protein that varies greatly between strains is unsuitable for vaccine development because the variation limits cross-protection.",
    "k": "Neisseria gonorrhoeae and meningitidis, Borrelia burgdorferi, Treponema pallidum, Streptococcus pyogenes, Staphylococcus aureus, Haemophilus influenzae; M protein belongs to S. pyogenes, not Neisseria.",
    "d": "Prefer NAAT/PCR over serology and culture for variable or poorly growing organisms; in gonorrhoea Gram stain shows intracellular diplococci in neutrophils and culture gives susceptibility.",
    "b": "Target conserved antigens in vaccines (toxoids, capsule conjugates, OMV vaccines); ceftriaxone for gonorrhoea with partner treatment, and cell-mediated immunity is required against intracellular survivors.",
    "src": "t3b-069"
   },
