     "Candidaemia: echinocandin first-line, remove CVC, repeat cultures, eye exam; step down to fluconazole",
     "Azole resistance: efflux pumps (CDR/MDR) and ERG11 mutations; echinocandin resistance: FKS1/2",
     "C. auris: ~90% azole-resistant, survives chlorhexidine, persists on surfaces, outbreaks – isolate, contact precautions, chlorine disinfection, screening"
