   "card": {
    "fk": "A zoonosis is a disease or infection that occurs naturally and repeatedly between animals and humans: anthropozoonosis from animal to human, zooanthropozoonosis from human to animal. The reservoir is a chronic, usually symptomless animal bearer in which the agent can be amplified, and a vector is an arthropod that transfers the agent biologically. More than 150 zoonotic diseases exist.",
    "v": [
     "Not zoonoses: transfer of bacterial toxin only, passive carriage of a human-selective pathogen in food, and the same independent disease arising separately in animals and humans.",
     "Four transmission cycles: one vertebrate reservoir (rabies); several vertebrates (Echinococcus multilocularis); vertebrate plus arthropod vector (West Nile); non-living environmental reservoir (Listeria in soil).",
     "To become an established human zoonosis the agent must multiply in humans, humans must be exposed frequently, and an efficient route plus a large reservoir must exist.",
     "Spread increases with climate change (vector range and season), biodiversity loss, deforestation and urbanisation, global travel, animal trade and intensive farming.",
     "Campylobacteriosis is the most reported zoonosis in Sweden; nephropathia epidemica (Puumala hantavirus from bank voles, inhaled dust) is the classic Norrland viral zoonosis.",
     "The Swedish anthrax strategy is to map historical anthrax farm sites with spore-contaminated burial grounds."
    ],
    "m": "A vector carries the agent inside itself and transmits it actively and is usually not sick; carriage of many agents on the surface is mechanical transfer and not zoonotic transmission.",
    "k": "Bacterial: Campylobacter, Salmonella, EHEC, Yersinia, Francisella, Leptospira, Listeria, Bacillus anthracis, Borrelia, Capnocytophaga. Viral: Puumala hantavirus, TBE, Sindbis, rabies, Ebola, SARS-CoV-2, influenza A.",
    "d": "Depends on the agent: culture and PCR from faeces, blood or urine; serology for hantavirus, TBE, Sindbis and Borrelia; PCR rather than culture for anthrax.",
    "b": "Surveillance programmes in animals and food, food hygiene, vector protection, vaccination where available (TBE, rabies post-exposure), notification, and specific advice to immunosuppressed patients about pets and raw animal feed.",
    "src": "t3b-009"
   },
