     "t": "VT",
     "q": "12",
     "x": "Tests HPV-related cancers; expected answer: penile cancer and non-melanoma skin cancer (the basal cell carcinoma option; cutaneous HPV is mainly linked to squamous cell skin cancer in immunosuppressed). Nasopharyngeal carcinoma is EBV-linked.",
     "k": false,
     "s": "HPV-associated non-cervical cancers"
