     "MAC (C5b–C9) lyses especially Neisseria",
     "Classical pathway: C1q binds IgM/IgG; best activator IgM",
     "Opsonins: C3b and IgG; not C5a, C3a, M protein",
     "Terminal complement/properdin deficiency → recurrent Neisseria; early components → SLE-like disease"
