     "q": "30",
     "x": "Tests viral neuroinvasion; expected answer: e.g. retrograde transport via motor neurons at the NMJ (polio, rabies), sensory nerve endings (HSV), olfactory route, Trojan-horse leukocytes (HIV) or brain endothelium (West Nile).",
     "k": false,
