     "y": 2024,
     "t": "VT",
     "q": "18",
     "x": "Tests viral entry; expected answer: host proteases (furin, TMPRSS2, cathepsins) cleave glycoproteins like HA or spike to activate fusion; non-enveloped viruses do not fuse and some viruses use both entry routes.",
     "k": false,
