     "Mycoplasma virulence factors: adherence, reactive oxygen species, phospholipase, antigenic variation; disease is primary atypical pneumonia in young adults",
     "Legionella lives in water and amoebae, spreads by aerosol, and survives in alveolar macrophages (Mip, adhesin)",
     "Legionnaires' disease is severe pneumonia in the elderly; diagnose with urine antigen and PCR",
