     "x": "Tests superantigens; expected answer: they bridge MHC II and TCR Vbeta outside the peptide groove, polyclonally activating a large fraction of T cells, and the resulting cytokine storm (TNF, IL-2, IFN-gamma) causes shock and organ failure.",
     "k": false,
