   "card": {
    "fk": "Viruses encode proteins that counteract almost every step of innate immunity and many steps of adaptive immunity, and they can also hide in sites with little immune surveillance. The aims are survival, replication and spread, and good evasion is what allows persistent infection.",
    "v": [
     "Innate targets: PRR sensing and IFN induction, IFN signal transduction, cytokine and chemokine production, NK activation, dendritic cell antigen presentation, complement and apoptosis.",
     "Influenza A NS1 binds RIG-I and blocks CARD activation so interferon is not produced; mutating NS1 abolishes pathogenicity, proving it is a virulence factor.",
     "Vaccinia virus secretes a soluble interferon alpha/beta decoy receptor.",
     "HIV-1 incorporates CD46, CD55 and CD59 into its envelope to resist complement lysis; HSV-1, HSV-2 and VZV bind C3b.",
     "Downregulation of MHC class I is the most common way to avoid cytotoxic T lymphocytes; other adaptive strategies are blocked antigen processing, killing lymphocytes, epitope drift and latency.",
     "Many viral proteins block apoptosis, which would otherwise kill the infected cell and protect the organism."
    ],
    "m": "Interferon antagonists act on the innate immune response, and MHC class I downregulation is the classic answer for evading cytotoxic T cells.",
    "k": "Influenza (NS1), Ebola (VP35), HCV (NS3/4A), HSV (ICP0), CMV (MHC I interference), HIV (Vpr, Vif, envelope complement regulators), vaccinia (IFN decoy receptor).",
    "d": "In immunosuppressed patients serology is unreliable, so quantitative PCR in blood is used to monitor CMV, EBV and BK virus.",
    "b": "Interferon has been used therapeutically; attenuated vaccines often have crippled IFN-antagonist genes; antiviral prophylaxis is used in the immunosuppressed.",
    "src": "t3b-071"
   },
