     "PPV23: T-independent, no memory, ineffective <2 years; PCV: T-dependent, memory, reduces carriage",
     "DTaP: diphtheria and tetanus toxoids + pertussis toxoid and adhesins; less reactogenic than whole-cell DTP",
     "Pertussis re-emergence: waning immunity, strain adaptation, adults infect infants",
     "BCG: live attenuated M. bovis (230 passages); protects against severe childhood TB only",
     "BCG problems: poor in tropics, no protection against infection or adult TB, affects skin test",
     "Reverse vaccinology (genome-based) for meningococcus B"
