   "card": {
    "fk": "Antiviral resistance comes from mutations in the drug-target gene that arise during replication and are selected by the drug. RNA viruses (and HIV reverse transcriptase) lack proofreading, with 1 error per 10^4–10^5 nucleotides (about 1 mutation per 1–10 genomes of 10 kb), versus 10^6–10^8 for proofreading DNA polymerases. Fast replication creates quasispecies in which resistant variants already exist. Combination therapy prevents resistance.",
    "v": [
     "RNA viruses: error-prone RdRp/RT without proofreading, giving a high mutation rate",
     "Error rate 10^-4–10^-5 (RNA) vs 10^-6–10^-8 (DNA, proofreading)",
     "Coronaviruses mutate less: nsp14 exonuclease proofreading",
     "Chronic infections (HIV, HBV, HCV) with long treatment are a special concern",
     "Combination therapy: simultaneous multiple resistance is very unlikely; higher potency",
     "Acyclovir resistance via TK mutation, so use foscarnet; amantadine resistance common"
    ],
    "m": "RNA viruses become resistant faster because their polymerases lack proofreading, which is why HIV is treated with drug combinations.",
    "k": "Mutation in the target gene during replication, then selection under drug pressure (quasispecies).",
    "d": "Genotypic resistance testing (sequencing) and viral load monitoring.",
    "b": "Combination therapy, high-barrier drugs, adherence, resistance testing before treatment.",
    "src": "t3b-175"
   },
