     "x": "Tests UTI and UPEC; expected answer: ≥10^5 CFU/ml shows significant bacteriuria; short female urethra near anus; virulence factors include type 1 and P fimbriae (adhesion), haemolysin, siderophores, capsule and LPS.",
     "k": false,
