   "card": {
    "fk": "Streptococcus pneumoniae is an alpha-haemolytic, lancet-shaped Gram-positive diplococcus carried in the nasopharynx. It is the leading cause of lobar pneumonia, otitis media, sinusitis and bacterial meningitis, and its polysaccharide capsule, with 98 variants, is the key virulence factor.",
    "v": [
     "Capsule protects from phagocytosis; pneumolysin is pro-inflammatory and forms pores; autolysin makes the bacterium fragile on plates",
     "Mucosal damage, often from a preceding viral infection, precedes invasion; bacteraemia occurs in 10-20%",
     "Lobar pneumonia: high fever with rigors, pleuritic pain, consolidation, CRP over 200",
     "Rigors arise from IL-1, IL-6 and TNF raising the hypothalamic set point",
     "Diagnosis: blood cultures, sputum culture with Gram stain (optochin-sensitive, alpha-haemolytic), urinary pneumococcal antigen, PCR (lytA), chest X-ray",
     "Urine antigen is rapid and unaffected by antibiotics but can stay positive for weeks",
     "PPV23 is T-cell-independent without memory and poor under 2 years; PCV conjugate works in infants, gives memory and herd immunity",
     "Penicillin is first-line; Swedish children have been vaccinated with PCV since 2009"
    ],
    "m": "Urine antigen testing identifies pneumonia (pneumococcus and Legionella), not urinary tract infection.",
    "k": "Anti-phagocytic polysaccharide capsule plus pneumolysin-driven inflammation after nasopharyngeal colonisation and mucosal damage.",
    "d": "Blood culture, sputum Gram stain and culture, urinary pneumococcal antigen, PCR and chest X-ray.",
    "b": "Penicillin as first-line therapy; prevention with conjugate vaccine in children and PPV23/PCV in the elderly and risk groups.",
    "src": "t3b-088"
   },
