     "t": "VT",
     "q": "18",
     "x": "Tests UTI pathogenesis; expected answer: e.g. type 1 fimbriae binding uroplakins in the bladder, P fimbriae binding kidney glycolipids, haemolysin damaging cells, capsule resisting phagocytosis and siderophores capturing iron.",
     "k": false,
     "s": "UPEC virulence factors"
