     "Risk: contact, trauma, moisture, crowding, cellular immunodeficiency; reinfection common",
     "Diagnosis: skin scrapings, hair, nail clippings → 10% KOH microscopy and Sabouraud culture",
     "Treatment: dry skin, topical azoles (miconazole, clotrimazole); nails/scalp systemic terbinafine"
